WITH x AS (SELECT payroll_month,department,SUM(punch_ot_hours) punch_overtime_hours,SUM(approved_ot_hours) approved_overtime_hours,SUM(paid_ot_hours) paid_overtime_hours FROM warehouse_monthly_employee GROUP BY 1,2) SELECT *, (paid_overtime_hours-punch_overtime_hours)/punch_overtime_hours paid_vs_computed_pct FROM x WHERE punch_overtime_hours>0 AND (paid_overtime_hours-punch_overtime_hours)/punch_overtime_hours>0.15;
